func (c *Core) tsiLookback(optInFirstPeriod, optInSecondPeriod int32) int32 {
	if optInFirstPeriod == IntegerDefault {
		optInFirstPeriod = 25
	} else if optInFirstPeriod < 2 || optInFirstPeriod > 100000 {
		return -1
	}
	if optInSecondPeriod == IntegerDefault {
		optInSecondPeriod = 13
	} else if optInSecondPeriod < 2 || optInSecondPeriod > 100000 {
		return -1
	}
	return 1 + c.emaLookback(optInFirstPeriod) + c.emaLookback(optInSecondPeriod)
}

