// TSILookback returns how many leading bars [Core.TSI] consumes before its
// first value: called with startIdx 0, its first value is at that bar.
//
// It takes the parameters of [Core.TSI] and returns [BadParam] for one out of
// range.
func (c *Core) TSILookback(optInFirstPeriod, optInSecondPeriod int) (int, error) {
	if !fitsInt32(optInFirstPeriod) {
		return 0, BadParam
	}
	if !fitsInt32(optInSecondPeriod) {
		return 0, BadParam
	}
	lookback := c.tsiLookback(int32(optInFirstPeriod), int32(optInSecondPeriod))
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// TSI computes the True Strength Index over bars startIdx through endIdx.
//
// True Strength Index: William Blau's double-smoothed momentum oscillator. The
// one-bar price change is smoothed twice with exponential averages, and the
// same pair of averages is applied to the magnitude of that change; the ratio
// of the two is scaled by 100. Dividing the smoothed signed momentum by the
// smoothed absolute momentum normalises the reading, so the result is bounded
// by -100 and +100 and comparable across instruments. The double smoothing is
// what separates it from a raw momentum plot: the curve is smooth enough to
// read while keeping far less lag than a single average of the same total
// length.
//
// Formula and more info at https://ta-lib.org/functions/tsi.
//
// Inputs, each at least endIdx+1 long:
