func (c *Core) tsiOpenAndFillInternal(inReal []float64, startIdx, optInFirstPeriod, optInSecondPeriod int32, outBegIdx, outNBElement *int32, outReal []float64) (*TSIStream, error) {
	sp := &TSIStream{core: c}
	if retCode := c.tsiOpenImpl(sp, inReal, startIdx, optInFirstPeriod, optInSecondPeriod, outBegIdx, outNBElement, outReal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) tsiOpenInternal(inReal []float64, startIdx, optInFirstPeriod, optInSecondPeriod int32) (*TSIStream, error) {
	sp := &TSIStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outReal [1]float64
	if retCode := c.tsiOpenImpl(sp, inReal, startIdx, optInFirstPeriod, optInSecondPeriod, &outBegIdx, &outNBElement, sink_outReal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// TSIOpen opens a live [TSIStream] on a warm-up history, oldest bar first, and
// returns it with its value at the last history bar, the value [Core.TSI]
// writes there.
//
// inReal is the history; the parameters are those of [Core.TSI].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.TSILookback] bars, and [BadParam] for a parameter out of range.
func (c *Core) TSIOpen(inReal []float64, optInFirstPeriod, optInSecondPeriod int) (*TSIStream, float64, error) {
	if !fitsInt32(optInFirstPeriod) {
		return nil, 0, BadParam
	}
	if !fitsInt32(optInSecondPeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.tsiOpenInternal(inReal, 0, int32(optInFirstPeriod), int32(optInSecondPeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// TSIOpenAndFill opens a stream as [Core.TSIOpen] does and also writes the
// outputs over the whole history, as [Core.TSI] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.TSILookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.TSIOpen], and [BadParam] for an output that is
// empty, too short or sharing memory.
func (c *Core) TSIOpenAndFill(inReal []float64, optInFirstPeriod, optInSecondPeriod int, outReal []float64) (*TSIStream, OutRange, error) {
	if !fitsInt32(optInFirstPeriod) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInSecondPeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.tsiLookback(int32(optInFirstPeriod), int32(optInSecondPeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.tsiOpenAndFillInternal(inReal, 0, int32(optInFirstPeriod), int32(optInSecondPeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
